print(f'October Meeting budgets: {oct_budgets}')
total_by_type = {}
with open('csv/expense.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['approved'] == 'Yes' and row['link_to_budget'] in oct_budgets:
            desc = row['expense_description']
            cost = float(row['cost'])
            total_by_type[desc] = total_by_type.get(desc, 0) + cost
for t, c in sorted(total_by_type.items()):
    print(f'{t}: {c}')
print(f'Total: {sum(total_by_type.values())}')

